   169	function getDistanceForDisplay(
   170	    hasRoute: boolean,
   171	    distanceInMeters: number,
   172	    unit: Unit | undefined,
   173	    rate: number | undefined,
   174	    translate: LocaleContextProps['translate'],
   175	    useShortFormUnit?: boolean,
   176	): string {
   177	    if (!hasRoute || !rate || !unit || !distanceInMeters) {
   178	        return translate('iou.fieldPending');
