   267	function getCustomUnitRateID(reportID: string, shouldUseDefault?: boolean) {
   268	    const allReports = ReportConnection.getAllReports();
   269	    const report = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`];
   270	    const parentReport = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${report?.parentReportID}`];
   271	    const policy = PolicyUtils.getPolicy(report?.policyID ?? parentReport?.policyID ?? '-1');
   272	    let customUnitRateID: string = CONST.CUSTOM_UNITS.FAKE_P2P_ID;
   273	
   274	    if (ReportUtils.isPolicyExpenseChat(report) || ReportUtils.isPolicyExpenseChat(parentReport)) {
   275	        const distanceUnit = Object.values(policy?.customUnits ?? {}).find((unit) => unit.name === CONST.CUSTOM_UNITS.NAME_DISTANCE);
   276	        const lastSelectedDistanceRateID = lastSelectedDistanceRates?.[policy?.id ?? '-1'] ?? '-1';
   277	        const lastSelectedDistanceRate = distanceUnit?.rates[lastSelectedDistanceRateID] ?? {};
   278	        if (lastSelectedDistanceRate.enabled && lastSelectedDistanceRateID && !shouldUseDefault) {
   279	            customUnitRateID = lastSelectedDistanceRateID;
   280	        } else {
   281	            customUnitRateID = getDefaultMileageRate(policy)?.customUnitRateID ?? '-1';
   282	        }
   283	    }
   284	
   285	    return customUnitRateID;
   286	}
